def as_base_exp(self):
    """Return base and exp of self.

    Explnation
    ==========

    If base is 1/Integer, then return Integer, -exp. If this extra
    processing is not needed, the base and exp properties will
    give the raw arguments

    Examples
    ========

    >>> from sympy import Pow, S
    >>> p = Pow(S.Half, 2, evaluate=False)
    >>> p.as_base_exp()
    (2, -2)
    >>> p.args
    (1/2, 2)

    """

    b, e = self.args
    if b.is_Rational and b.p == 1 and b.q != 1:
        return Integer(b.q), -e
    return b, e

def _eval_adjoint(self):
    from sympy.functions.elementary.complexes import adjoint
    i, p = self.exp.is_integer, self.base.is_positive
    if i:
        return adjoint(self.base)**self.exp
    if p:
        return self.base**adjoint(self.exp)
    if i is False and p is False:
        expanded = expand_complex(self)
        if expanded != self:
            return adjoint(expanded)

def _eval_conjugate(self):
    from sympy.functions.elementary.complexes import conjugate as c
    i, p = self.exp.is_integer, self.base.is_positive
    if i:
        return c(self.base)**self.exp
    if p:
        return self.base**c(self.exp)
    if i is False and p is False:
        expanded = expand_complex(self)
        if expanded != self:
            return c(expanded)
    if self.is_extended_real:
        return self

def _eval_transpose(self):
    from sympy.functions.elementary.complexes import transpose
    if self.base == S.Exp1:
        return self.func(S.Exp1, self.exp.transpose())
    i, p = self.exp.is_integer, (self.base.is_complex or self.base.is_infinite)
    if p:
        return self.base**self.exp
    if i:
        return transpose(self.base)**self.exp
    if i is False and p is False:
        expanded = expand_complex(self)
        if expanded != self:
            return transpose(expanded)

def _eval_expand_power_exp(self, **hints):
    """a**(n + m) -> a**n*a**m"""
    b = self.base
    e = self.exp
    if b == S.Exp1:
        from sympy import Sum, Product
        if isinstance(e, Sum) and e.is_commutative:
            return Product(self.func(b, e.function), *e.limits)
    if e.is_Add and e.is_commutative:
        expr = []
        for x in e.args:
            expr.append(self.func(b, x))
        return Mul(*expr)
    return self.func(b, e)

def _eval_expand_power_base(self, **hints):
    """(a*b)**n -> a**n * b**n"""
    force = hints.get('force', False)

    b = self.base
    e = self.exp
    if not b.is_Mul:
        return self

    cargs, nc = b.args_cnc(split_1=False)

    # expand each term - this is top-level-only
    # expansion but we have to watch out for things
    # that don't have an _eval_expand method
    if nc:
        nc = [i._eval_expand_power_base(**hints)
            if hasattr(i, '_eval_expand_power_base') else i
            for i in nc]

        if e.is_Integer:
            if e.is_positive:
                rv = Mul(*nc*e)
            else:
                rv = Mul(*[i**-1 for i in nc[::-1]]*-e)
            if cargs:
                rv *= Mul(*cargs)**e
            return rv

        if not cargs:
            return self.func(Mul(*nc), e, evaluate=False)

        nc = [Mul(*nc)]

    # sift the commutative bases
    other, maybe_real = sift(cargs, lambda x: x.is_extended_real is False,
        binary=True)
    def pred(x):
        if x is S.ImaginaryUnit:
            return S.ImaginaryUnit

def _parallel_dict_from_expr_if_gens(exprs, opt):
    """Transform expressions into a multinomial form given generators. """
    k, indices = len(opt.gens), {}

    for i, g in enumerate(opt.gens):
        indices[g] = i

    polys = []

    for expr in exprs:
        poly = {}

        if expr.is_Equality:
            expr = expr.lhs - expr.rhs

        for term in Add.make_args(expr):
            coeff, monom = [], [0]*k

            for factor in Mul.make_args(term):
                if not _not_a_coeff(factor) and factor.is_Number:
                    coeff.append(factor)
                else:
                    try:
                        if opt.series is False:
                            base, exp = decompose_power(factor)

                            if exp < 0:
                                exp, base = -exp, Pow(base, -S.One)
                        else:
                            base, exp = decompose_power_rat(factor)

                        monom[indices[base]] = exp
                    except KeyError:
                        if not factor.free_symbols.intersection(opt.gens):
                            coeff.append(factor)
                        else:
                            raise PolynomialError("%s contains an element of "
                                                  "the set of generators." % factor)

            monom = tuple(monom)

            if monom in poly:
                poly[monom] += Mul(*coeff)
            else:
                poly[monom] = Mul(*coeff)

        polys.append(poly)

    return polys, opt.gens


def _parallel_dict_from_expr_no_gens(exprs, opt):
    """Transform expressions into a multinomial form and figure out generators. """
    if opt.domain is not None:
        def _is_coeff(factor):
            return factor in opt.domain
    elif opt.extension is True:
        def _is_coeff(factor):
            return factor.is_algebraic
    elif opt.greedy is not False:
        def _is_coeff(factor):
            return factor is S.ImaginaryUnit
    else:
        def _is_coeff(factor):
            return factor.is_number

    gens, reprs = set(), []

    for expr in exprs:
        terms = []

        if expr.is_Equality:
            expr = expr.lhs - expr.rhs

        for term in Add.make_args(expr):
            coeff, elements = [], {}

            for factor in Mul.make_args(term):
                if not _not_a_coeff(factor) and (factor.is_Number or _is_coeff(factor)):
                    coeff.append(factor)
                else:
                    if opt.series is False:
                        base, exp = decompose_power(factor)

                        if exp < 0:
                            exp, base = -exp, Pow(base, -S.One)
                    else:
                        base, exp = decompose_power_rat(factor)

                    elements[base] = elements.setdefault(base, 0) + exp
                    gens.add(base)

            terms.append((coeff, elements))

        reprs.append(terms)

    gens = _sort_gens(gens, opt=opt)
    k, indices = len(gens), {}

    for i, g in enumerate(gens):
        indices[g] = i

    polys = []

    for terms in reprs:
        poly = {}

        for coeff, term in terms:
            monom = [0]*k

            for base, exp in term.items():
                monom[indices[base]] = exp

            monom = tuple(monom)

            if monom in poly:
                poly[monom] += Mul(*coeff)
            else:
                poly[monom] = Mul(*coeff)

        polys.append(poly)

    return polys, tuple(gens)


def _dict_from_expr_if_gens(expr, opt):
    """Transform an expression into a multinomial form given generators. """
    (poly,), gens = _parallel_dict_from_expr_if_gens((expr,), opt)
    return poly, gens


def _dict_from_expr_no_gens(expr, opt):
    """Transform an expression into a multinomial form and figure out generators. """
    (poly,), gens = _parallel_dict_from_expr_no_gens((expr,), opt)
    return poly, gens


